def date_the_existing_hand_overs(apps, schema_editor):
    """Date the site visit stage for leads that already have a BDE.

    The hand-over was never stored, so it is read back from what the activity
    log kept, taking the earliest of: the "Assigned to BDE" entry the Assign BDE
    button writes, and the BDE's own first entry on the lead (they were working
    it by then — and a BDE who created the lead had it from the start).

    The log records the first trace of the BDE, which can come after the
    hand-over itself. A lead had its BDE before its PO was signed and before it
    was pushed to documentation, so a log date later than either is pulled back
    to it.

    A lead with no trace in the log stays undated rather than being given a
    guess: it still counts as having reached the stage, it just cannot be placed
    in a date range.
    """
    from datetime import datetime, time

    from django.db.models import F, Min
    from django.utils import timezone

    Lead = apps.get_model('leads', 'Lead')
    ActivityLog = apps.get_model('leads', 'ActivityLog')

    pending = Lead.objects.filter(bde__isnull=False, bde_assigned_at__isnull=True)
    if not pending.exists():
        return

    def earliest(logs):
        return dict(logs.filter(lead__in=pending).order_by()
                    .values('lead_id').annotate(t=Min('created_at'))
                    .values_list('lead_id', 't'))

    assigned = earliest(ActivityLog.objects.filter(description__startswith='Assigned to BDE'))
    by_bde = earliest(ActivityLog.objects.filter(actor_id=F('lead__bde_id')))
    local = timezone.get_default_timezone()

    dated = []
    rows = pending.values_list('id', 'pushed_to_documentation_at', 'site_visit__po_signed_date')
    for lead_id, pushed_at, po_day in rows.iterator():
        found = [t for t in (assigned.get(lead_id), by_bde.get(lead_id)) if t]
        if not found:
            continue
        when = min(found)
        signed_at = datetime.combine(po_day, time.min, tzinfo=local) if po_day else None
        for no_later_than in (pushed_at, signed_at):
            if no_later_than and no_later_than < when:
                when = no_later_than
        dated.append(Lead(id=lead_id, bde_assigned_at=when))
    Lead.objects.bulk_update(dated, ['bde_assigned_at'], batch_size=500)


